import sys, itertools

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
E = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]

def greedy():
    done = [False] * n
    order = []
    for _ in range(n):
        pick = -1
        for v in range(n):
            if not done[v] and all(done[a] for a, b in E if b == v):
                pick = v
                break
        if pick < 0:
            return None
        done[pick] = True
        order.append(pick)
    return order

res = None
if n <= 7:
    for p in itertools.permutations(range(n)):
        pos = {v: i for i, v in enumerate(p)}
        if all(pos[a] < pos[b] for a, b in E):
            res = list(p)
            break
else:
    res = greedy()
print(-1 if res is None else ' '.join(map(str, res)))

